-- ----------------------------
-- Table structure for procurements
-- ----------------------------
DROP TABLE IF EXISTS `procurements`;
CREATE TABLE `procurements`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `type` enum('repair','credit','cash') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `fiscal_year` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `doc_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'เลขที่หนังสือ',
  `doc_date` date NOT NULL COMMENT 'วันที่เอกสาร',
  `subject` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'เรื่อง',
  `requester_id` int NOT NULL COMMENT 'ผู้ขอ (User ID)',
  `repair_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'สาเหตุ/อาการ (repair)',
  `repair_detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'รายละเอียดการซ่อม (repair)',
  `buy_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'เหตุผลความจำเป็น (credit)',
  `receipt_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'เลขที่ใบเสร็จ (cash)',
  `vendor_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'ร้านค้า',
  `delivery_date` date NULL DEFAULT NULL COMMENT 'กำหนดส่งมอบ',
  `total_amount` decimal(15, 2) NULL DEFAULT 0.00,
  `inspector_id` int NULL DEFAULT NULL COMMENT 'ผู้ตรวจรับ',
  `supply_officer_id` int NULL DEFAULT NULL COMMENT 'เจ้าหน้าที่พัสดุ',
  `director_id` int NULL DEFAULT NULL COMMENT 'ผู้อำนวยการ',
  `head_officer_id` int NULL DEFAULT NULL COMMENT 'หัวหน้าส่วนราชการ (for credit)',
  `status` enum('draft','pending','approved','completed','cancelled') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'draft',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `requester_id`(`requester_id` ASC) USING BTREE,
  CONSTRAINT `procurements_ibfk_1` FOREIGN KEY (`requester_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

