INSERT INTO `procurement_items` VALUES (1, 1, NULL, 'วัสดุสำนักงานและแบบพิมพ์จำนวน 36 รายการ', 36, 703.47, 25324.92, '2026-02-11 17:15:01');
INSERT INTO `procurements` VALUES (1, 'credit', '2569', '71/2569', '2026-01-12', 'รายงานขออนุมัติจัดซื้อวัสดุสำนักงานและแบบพิมพ์', 1, NULL, NULL, 'ด้วยส่วนคลัง ส่วนช่วยอำนวยการ ส่วนบริหารจัดการคดี ส่วนไกล่เกลี่ยและประนอมข้อพิพาท ส่วนบริการประชาชนและประชาสัมพันธ์ ได้ขออนุมัติเบิกใช้วัสดุสำนักงานและแบบพิมพ์สำหรับใช้ในการปฏิบัติราชการของส่วนงานต่างๆ แต่ปรากฏว่าวัสดุสำนักงานและแบบพิมพ์ดังกล่าวมีไม่เพียงพอให้เบิกใช้ เพื่อให้การปฏิบัติราชการเป็นไปด้วยความสะดวกเรียบร้อยและ      ไม่เกิดความเสียหายต่อทางราชการจึงจำเป็นต้องจัดซื้อวัสดุสำนักงานและแบบพิมพ์ ดังกล่าว', NULL, 'บริษัท นิวง่วนแสงไทย 2003 จำกัด', NULL, 25324.92, 40, 2, 81, NULL, 'pending', '2026-02-11 17:15:01', '2026-02-11 17:15:01');
INSERT INTO `service_requests` VALUES (1, 1, 'repair', 0, 'Drum หมึกเครื่องพิมพ์ Pantum', 'P3010DW', 'ในวันที่  9 กุมภาพันธ์ 2569 ข้าพเจ้าพบปัญหาเครื่องพิมพ์ที่ใช้งานส่วนตัวในส่วนเทคโนโลยีสารสนเทศ  แจ้งรหัสปัญหา “Drum End Soon” ปัญหาดังกล่าวคือ การแจ้งว่าจะครบรอบการใช้งาน Drum ของเครื่องนี้แล้ว  จะต้องทำการเปลี่ยน Drum ไม่เช่นนั้นเครื่องพิมพ์จะไม่สามารถสั่งพิมพ์เอกสารได้  เนื่องจากระบบมีการกำหนดว่า Drum เครื่องพิมพ์จะมีรอบของการเปลี่ยนเนื่องจากการสึกหรอจากการใช้งานของหัว Drum ที่เชื่อมต่อกับตลับหมึก', NULL, NULL, NULL, 'pending', NULL, NULL, 'templates/word_jobs/admin_13022026_0950.docx', '2026-02-13 15:50:52', '2026-02-13 15:50:52');
INSERT INTO `service_requests` VALUES (2, 1, 'purchase', NULL, 'Access Point Router TP-LINK', '(Archer AX100) Wireless AX1500 Dual band Gigabit', 'ขอซ่อมอุปกรณ์กระจายสัญญาณอินเตอร์ไร้สาย (Access Point) เพื่อติดตั้งในห้องปฏิบัติงานผู้อำนวยการฯ', 1, 19, 'ด้วยข้าพเจ้า  นายเอกวิทย์  ลาดล้าย  ได้รับแจ้งปัญหาการใช้งานอินเตอร์เน็ตห้องปฏิบัติงานท่านผู้อำนวยการฯ  พบปัญหาอินเตอร์เน็ตสัญญาณขาดหาย  จากการตรวจสอบพบว่า อุปกรณ์กระจายสัญญาณเป็นอุปกรณ์ที่รองรับแบนด์วิธ 2.4 Ghz ทำให้การกระจายสัญญาณไม่เสถียร  และมีปัญหาสัญญาณหลุดบ่อยครั้ง  จึงจำเป็นต้องจัดหาอุปกรณ์กระจายสัญญาณทดแทน', 'pending', NULL, NULL, 'templates/word_jobs/admin_16022026_0814.docx', '2026-02-16 14:14:32', '2026-02-16 14:14:32');
